#[cfg(test)]
mod tests {
    use bloom_offchain_cardano::validation_rules::ValidationRules;
    use cardano_chain_sync::atomic_flow::BlockEvents;
    use cardano_explorer::AnyExplorer;
    use cml_chain::certs::Credential;
    use cml_chain::transaction::Transaction;
    use cml_core::serialization::Deserialize;
    use cml_crypto::{Ed25519KeyHash, ScriptHash};
    use either::Right;
    use futures::FutureExt;
    use spectrum_offchain_cardano::data::PoolId;
    use spectrum_offchain_cardano::deployment::{
        DeployedValidators as DexValidators, ProtocolDeployment as DexDeployment,
    };
    use spectrum_offchain_cardano::event_pipeline::read_events::read_events;
    use spectrum_offchain_cardano::persistent_index::IndexRocksDB;
    use splash_dao_offchain::deployment::ProtocolTokens;
    use splash_dao_offchain::deployment::{
        DeployedValidators as DaoValidators, ProtocolDeployment as DaoDeployment,
    };
    use splash_dao_offchain::entities::onchain::smart_farm::FarmId;
    use splash_lp_index::config::AppConfig;
    use splash_lp_index::context::RuntimeContext;
    use splash_lp_index::pipeline::log_events::log_event;
    use splash_lp_index::pipeline::resolve_gauges::translate_events;
    use splash_lp_index::position_db::event_log::EventLog;
    use splash_lp_index::position_db::export_feed::ExportEventFeed;
    use splash_lp_index::position_db::mature_events::MatureEvents;
    use splash_lp_index::position_db::PositionDB;
    use splash_lp_index::ve_index::VoteEscrowDB;
    use splash_testing::db_path::DBPath;
    use std::collections::HashSet;
    use splash_yf_offchain::ve_config::VeConfig;

    #[tokio::test]
    #[ignore]
    async fn process_export_mature_events_with_pre_activated_farm() {
        let config_path = "resources/preprod.config.json";
        let dex_deployment_path = "../bloom-cardano-agent/resources/preprod.deployment.json";
        let dao_deployment_path = "resources/preprod.dao.deployment.json";
        let protocol_tokens_path = "resources/preprod.tokens.json";
        let validation_rules_path = "../bloom-cardano-agent/resources/validation-rules.json";

        let raw_config = std::fs::read_to_string(config_path).expect("Cannot load configuration file");
        let config: AppConfig = serde_json::from_str(&raw_config).expect("Invalid configuration file");

        let raw_deployment =
            std::fs::read_to_string(dex_deployment_path).expect("Cannot load DEX deployment file");
        let dex_validators: DexValidators =
            serde_json::from_str(&raw_deployment).expect("Invalid deployment file");

        let raw_deployment =
            std::fs::read_to_string(dao_deployment_path).expect("Cannot load DAO deployment file");
        let dao_validators: DaoValidators =
            serde_json::from_str(&raw_deployment).expect("Invalid deployment file");

        let raw_tokens = std::fs::read_to_string(protocol_tokens_path).expect("Cannot load DAO assets file");
        let dao_tokens: ProtocolTokens = serde_json::from_str(&raw_tokens).expect("Invalid deployment file");

        let raw_validation_rules =
            std::fs::read_to_string(validation_rules_path).expect("Cannot load bounds file");
        let validation_rules: ValidationRules =
            serde_json::from_str(&raw_validation_rules).expect("Invalid bounds file");

        let explorer = AnyExplorer::new(&config.explorer, config.network_id)
            .await
            .expect("Explorer initialization failed");

        let dex_protocol_deployment = DexDeployment::unsafe_pull(dex_validators, &explorer).await;
        let dao_protocol_deployment = DaoDeployment::unsafe_pull(dao_validators, &explorer).await;

        let persistable_entites = HashSet::from([
            dex_protocol_deployment.balance_fn_pool_v1.hash,
            dex_protocol_deployment.balance_fn_pool_v2.hash,
            dex_protocol_deployment.const_fn_pool_v1.hash,
            dex_protocol_deployment.const_fn_pool_v2.hash,
            dex_protocol_deployment.const_fn_pool_fee_switch.hash,
            dex_protocol_deployment.const_fn_pool_fee_switch_v2.hash,
            dex_protocol_deployment.const_fn_pool_fee_switch_bidir_fee.hash,
            dex_protocol_deployment.royalty_pool.hash,
            dex_protocol_deployment.stable_fn_pool_t2t.hash,
            dao_protocol_deployment.smart_farm.hash,
            dao_protocol_deployment.farm_factory.hash,
            dao_protocol_deployment.wp_factory.hash,
            dao_protocol_deployment.ve_factory.hash,
        ]);
        let cx = RuntimeContext {
            dex_deployment: dex_protocol_deployment,
            dao_deployment: dao_protocol_deployment,
            dao_tokens,
            pool_validation: validation_rules.pool,
            harvest_limits: config.harvest_limits,
            splash_policy_id: ScriptHash::from_hex(&config.splash_policy_id_hex).unwrap(),
            network_id: config.network_id,
        };

        let confirmation_blocks_delay = 5;

        let db_path = DBPath::new("position_db");
        let db = PositionDB::new(&db_path, confirmation_blocks_delay, VeConfig { epoch_start: 0, slots_in_epoch: 10 });
        let gauges_db_path = DBPath::new("gauges_index");
        let gauges_db = VoteEscrowDB::new(&gauges_db_path);

        let utxo_db_path = DBPath::new("utxo_index");
        let utxo_index = IndexRocksDB::new(&utxo_db_path);

        let pid = PoolId::random();
        let fid = FarmId::random();
        let account = Credential::new_pub_key(Ed25519KeyHash::from([0u8; 28]));

        let pool_created_tx_raw = "";
        let farm_activated_tx_raw = "";
        let farm_created_tx_raw = "";
        let user_deposit_tx_raw = "";

        let txs_ordering_to_simulate = vec![
            pool_created_tx_raw,
            farm_activated_tx_raw,
            farm_created_tx_raw,
            user_deposit_tx_raw,
        ];

        for (fake_block_num, raw_tx) in txs_ordering_to_simulate.into_iter().enumerate() {
            let tx_to_run = Transaction::from_cbor_bytes(hex::decode(raw_tx).unwrap().as_ref()).unwrap();
            let block_num = fake_block_num as u64;
            let block_slot = block_num * 10;
            let block_event_with_tx = BlockEvents::RollForward {
                events: vec![Right(tx_to_run)],
                block_num,
                block_slot,
            };

            read_events(block_event_with_tx, &cx, &utxo_index, &persistable_entites)
                .then(|events| translate_events(events, &gauges_db))
                .then(|events| log_event(events, &db))
                .await;

            db.batch_append(block_slot + confirmation_blocks_delay + 1, vec![])
                .await;

            let ok = db.try_process_mature_events().await;
            assert!(ok)
        }

        let last_event = db.next().await;

        let account_is_activated = last_event.map(|(_, event)| event.update.created_at);

        assert_eq!(account_is_activated, Some(1));
    }
}
